function Assert-LastExitCode([string]$Step) {
    if ($LASTEXITCODE -ne 0) { throw "$Step fallo con codigo de salida $LASTEXITCODE." }
}

function Decode-Utf8Base64([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Value))
}

function Read-Normalized([string]$RelativePath) {
    $path = Join-Path $RepoRoot $RelativePath
    if (-not (Test-Path $path -PathType Leaf)) { throw "Falta $RelativePath." }
    return ([System.IO.File]::ReadAllText($path,[System.Text.Encoding]::UTF8)).Replace("`r`n","`n").Replace("`r","`n")
}

function Write-Utf8NoBomLf([string]$RelativePath,[string]$Content) {
    $path = Join-Path $RepoRoot $RelativePath
    $directory = Split-Path -Parent $path
    if ($directory -and -not (Test-Path $directory -PathType Container)) {
        New-Item -ItemType Directory -Path $directory -Force | Out-Null
    }
    [System.IO.File]::WriteAllText($path,$Content.Replace("`r`n","`n").Replace("`r","`n"),[System.Text.UTF8Encoding]::new($false))
}

function Replace-ExactOnce(
    [string]$RelativePath,
    [string]$OldText,
    [string]$NewText,
    [string]$AlreadyMarker,
    [string]$Description) {

    $content = Read-Normalized $RelativePath
    if ($content.Contains($AlreadyMarker)) {
        Write-Host "OK: $Description ya estaba aplicado."
        return
    }

    $first = $content.IndexOf($OldText,[System.StringComparison]::Ordinal)
    if ($first -lt 0) { throw "No se encontro el bloque esperado para $Description en $RelativePath." }

    $second = $content.IndexOf($OldText,$first + $OldText.Length,[System.StringComparison]::Ordinal)
    if ($second -ge 0) { throw "El bloque de $Description aparece mas de una vez en $RelativePath." }

    Write-Utf8NoBomLf $RelativePath $content.Remove($first,$OldText.Length).Insert($first,$NewText)
    Write-Host "OK: $Description aplicado."
}

function Restore-GeneratedTypeScriptState {
    $relativePath = "apps/web/tsconfig.app.tsbuildinfo"
    git ls-files --error-unmatch -- $relativePath *> $null
    if ($LASTEXITCODE -ne 0) {
        $global:LASTEXITCODE = 0
        return
    }

    $status = git status --porcelain=v1 -- $relativePath
    if ($status) {
        git restore --worktree -- $relativePath
        Assert-LastExitCode "Restaurar tsbuildinfo"
        Write-Host "Restaurado $relativePath por ser salida incremental rastreada."
    }
}

function Get-ChangedPaths {
    $tracked = @(git diff --name-only)
    Assert-LastExitCode "Leer cambios tracked"
    $untracked = @(git ls-files --others --exclude-standard)
    Assert-LastExitCode "Leer cambios untracked"
    return @($tracked + $untracked | Where-Object { $_ } | Sort-Object -Unique)
}

function Assert-InventorySubset {
    $allowed = @{}
    foreach ($path in $PermanentPaths) { $allowed[$path] = $true }
    foreach ($path in Get-ChangedPaths) {
        if (-not $allowed.ContainsKey($path)) { throw "Ruta fuera del inventario BL-MVP-067: $path" }
    }
}

function Move-AnalysisEmptyStateAfterSourceContext {
    $relativePath = "apps/web/src/routes/editorial/LinguisticAnalysisStructurePage.tsx"
    $content = Read-Normalized $relativePath

    $emptyMarker = "      {data?.lyricsRevisionId && !revision ? ("
    $contextMarker = "      {data?.lyricsRevisionId ? (`n        <section className=`"linguistic-analysis__context`""
    $editorMarker = "      {data?.lyricsRevisionId ? (`n        <LinguisticAnalysisEditor"

    $emptyStart = $content.IndexOf(
        $emptyMarker,
        [System.StringComparison]::Ordinal)
    $contextStart = $content.IndexOf(
        $contextMarker,
        [System.StringComparison]::Ordinal)
    $editorStart = $content.IndexOf(
        $editorMarker,
        [System.StringComparison]::Ordinal)

    if ($emptyStart -lt 0 -or $contextStart -lt 0 -or $editorStart -lt 0) {
        throw "No se pudieron localizar los bloques de heading/empty-state BL067."
    }

    if ($contextStart -lt $emptyStart -and $emptyStart -lt $editorStart) {
        Write-Host "OK: empty state BL067 ya esta despues del H2 de fuente."
        return
    }

    if (-not ($emptyStart -lt $contextStart -and $contextStart -lt $editorStart)) {
        throw "Orden inesperado de bloques en UI-MVP-024; no se mueve contenido a ciegas."
    }

    $emptyBlock = $content.Substring(
        $emptyStart,
        $contextStart - $emptyStart)

    $withoutEmpty = $content.Remove(
        $emptyStart,
        $contextStart - $emptyStart)

    $newEditorStart = $withoutEmpty.IndexOf(
        $editorMarker,
        [System.StringComparison]::Ordinal)

    if ($newEditorStart -lt 0) {
        throw "No se encontro el editor BL067 despues de retirar temporalmente el empty state."
    }

    $updated = $withoutEmpty.Insert(
        $newEditorStart,
        $emptyBlock)

    Write-Utf8NoBomLf $relativePath $updated
    Write-Host "OK: empty state BL067 movido despues de Fuente exacta para jerarquia H1-H2-H3."
}

function Resolve-GitBash {
    foreach ($candidate in @("C:\Program Files\Git\bin\bash.exe","C:\Program Files\Git\usr\bin\bash.exe")) {
        if (Test-Path $candidate -PathType Leaf) { return $candidate }
    }
    $bashCommand = Get-Command bash.exe -ErrorAction SilentlyContinue
    if ($null -ne $bashCommand) { return $bashCommand.Source }
    throw "No se encontro Git Bash real."
}

